A = []

A.append(dict(
slug='melanggar-kovenan-bank-langkah-pemilik-usaha',
seo_title='Melanggar Kovenan Bank: Langkah Pemilik Usaha',
title='Melanggar Kovenan Bank: Langkah yang Perlu Dilakukan Pemilik Usaha Lebih Dulu',
description='Rasio melewati batas kovenan di perjanjian kredit bukan berarti kredit langsung ditarik. Ini jenis kovenan, langkah sebelum bank menghubungi, dan opsi waiver atau restrukturisasi.',
keyword='kovenan bank', category='Kredit Bank', minutes=6,
cta={'href':'/konsultan-kredit-bank/','label':'Konsultan Kredit Bank'},
wa='Halo FA Indonesia, rasio perusahaan saya melewati kovenan bank. Bagaimana langkahnya?',
sources=[['https://www.ojk.go.id/','Otoritas Jasa Keuangan']],
related=['restrukturisasi-kredit-perusahaan-skema-dokumen','dscr-adalah-cara-menghitung-kredit-bank','rasio-keuangan-yang-dilihat-bank','slik-ojk-perusahaan-pengurus-kolektibilitas'],
body_html='''<p>Perjanjian kredit korporasi hampir selalu memuat kovenan, yaitu janji debitur untuk menjaga hal tertentu, misalnya rasio keuangan atau tidak membagikan dividen sebelum syarat dipenuhi. Ketika angka laporan akhir tahun menunjukkan satu rasio melewati batas, banyak pemilik panik. Padahal pelanggaran kovenan tidak otomatis berarti kredit ditarik. Yang menentukan adalah cara Anda menanganinya.</p>
<h2>Jenis Kovenan yang Umum</h2>
''' + T(['Jenis','Contoh','Yang sering terlewat'],[
 ['Kovenan keuangan','DSCR minimal, DER maksimal, current ratio minimal, ekuitas minimal','Batas dihitung dari laporan audited, bukan angka internal'],
 ['Kovenan positif','Menyampaikan laporan keuangan tepat waktu, menjaga asuransi agunan, menjaga izin usaha','Terlambat kirim laporan tercatat sebagai pelanggaran sendiri'],
 ['Kovenan negatif','Tidak menambah utang, tidak menjaminkan aset ke pihak lain, tidak membagi dividen, tidak mengubah pemegang saham','Berlaku pula untuk transaksi pihak berelasi'],
 ['Cross default','Gagal bayar di bank lain dianggap gagal bayar di bank ini','Satu masalah kecil di kreditur lain bisa menjalar']]) + '''
<h2>Langkah Sebelum Bank yang Menghubungi Anda</h2>
<ol><li><b>Baca ulang klausulnya.</b> Cari definisi rasio, tanggal pengujian, masa pemulihan (cure period), dan konsekuensi yang tertulis. Banyak perhitungan rasio di perjanjian punya definisi khusus yang berbeda dari buku teks.</li>
<li><b>Hitung ulang dengan definisi bank.</b> Kadang pelanggaran hanya akibat perbedaan klasifikasi, misalnya utang pemegang saham masuk atau keluar dari perhitungan.</li>
<li><b>Cari penyebabnya.</b> Satu kali kejadian (proyek tertunda, piutang besar belum tertagih) berbeda dengan tren yang memburuk.</li>
<li><b>Siapkan rencana pemulihan.</b> Proyeksi arus kas, tindakan korektif, dan kapan rasio kembali sesuai.</li>
<li><b>Hubungi bank lebih dulu.</b> Relationship manager yang mendengar dari debitur sebelum menemukannya sendiri biasanya lebih terbuka mencari jalan tengah.</li></ol>
<h2>Opsi yang Biasanya Tersedia</h2>
<ul><li><b>Waiver.</b> Bank menyetujui tidak menindaklanjuti pelanggaran untuk periode tertentu, kadang dengan biaya atau syarat tambahan.</li>
<li><b>Amandemen kovenan.</b> Batas rasio disesuaikan bila bisnis memang berubah, misalnya setelah ekspansi.</li>
<li><b>Tambahan jaminan atau setoran modal.</b> Pemegang saham menambah ekuitas atau jaminan untuk memperbaiki rasio.</li>
<li><b>Restrukturisasi.</b> Jadwal pembayaran diubah bila masalahnya arus kas. Skema dan dokumennya ada di <a href="/artikel/restrukturisasi-kredit-perusahaan-skema-dokumen/">artikel restrukturisasi kredit</a>.</li></ul>
<h2>Yang Sebaiknya Dihindari</h2>
<ul><li>Mengubah angka atau klasifikasi laporan supaya rasio terlihat lolos. Selain berisiko hukum, ini merusak hubungan dengan bank dan tercatat di rekam jejak perusahaan.</li>
<li>Diam sampai bank menegur.</li>
<li>Menambah utang di bank lain tanpa izin, karena bisa memicu pelanggaran kovenan negatif.</li>
<li>Menarik dividen atau pinjaman pemegang saham saat rasio sedang bermasalah.</li></ul>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu membaca ulang perjanjian kredit, menghitung rasio sesuai definisi bank, menyusun rencana pemulihan dan proyeksi arus kas, serta mendampingi pembicaraan dengan bank. Pengalaman kami mencakup pendampingan kredit perbankan kumulatif lebih dari Rp1,1 triliun. Silakan lihat <a href="/konsultan-kredit-bank/">layanan konsultan kredit bank</a>. Pembahasan rasio yang biasa diuji ada di <a href="/artikel/dscr-adalah-cara-menghitung-kredit-bank/">artikel DSCR</a>.</p>''',
faq=[['Apakah melanggar kovenan membuat kredit langsung jatuh tempo?','Tergantung perjanjian. Banyak perjanjian memberi masa pemulihan dan hak bank, bukan kewajiban, untuk mempercepat jatuh tempo. Dalam praktik, bank lebih sering membuka pembicaraan waiver atau amandemen.'],
['Apakah waiver selalu berbayar?','Tidak selalu. Bank bisa meminta biaya, bunga yang disesuaikan, atau syarat tambahan, tergantung seberapa besar pelanggaran dan hubungan debitur.'],
['Bagaimana pengaruhnya ke kolektibilitas?','Pelanggaran kovenan dengan pembayaran tetap lancar tidak otomatis menurunkan kolektibilitas. Penurunan kolektibilitas terutama dipicu keterlambatan bayar atau penilaian prospek usaha oleh bank.'],
['Kapan sebaiknya menghubungi bank?','Begitu Anda melihat rasio akan melewati batas, idealnya sebelum laporan resmi dikirim.']]))

A.append(dict(
slug='laporan-keuangan-konsolidasian-grup-usaha-keluarga',
seo_title='Laporan Keuangan Konsolidasian Grup Usaha Keluarga',
title='Laporan Keuangan Konsolidasian untuk Grup Usaha Keluarga: Kapan Dibutuhkan dan Cara Menyusunnya',
description='Banyak grup usaha keluarga punya beberapa PT tanpa laporan gabungan. Ini kapan konsolidasi dibutuhkan bank dan investor, langkah menyusunnya, dan jebakan transaksi antar PT.',
keyword='laporan keuangan konsolidasian', category='Laporan Keuangan', minutes=7,
cta={'href':'/jasa-penyusunan-laporan-keuangan/','label':'Jasa Penyusunan Laporan Keuangan'},
wa='Halo FA Indonesia, saya punya beberapa PT dan butuh laporan keuangan konsolidasian.',
sources=[['https://web.iaiglobal.or.id/','Ikatan Akuntan Indonesia, SAK Online'],['https://www.ojk.go.id/','Otoritas Jasa Keuangan']],
related=['laporan-keuangan-bankable-investor-ready','pisahkan-uang-pribadi-dan-perusahaan','psak-119-entitas-anak-tanpa-akuntabilitas-publik','kapan-perusahaan-wajib-diaudit'],
body_html='''<p>Banyak pemilik usaha mengelola beberapa PT sekaligus: satu untuk operasional, satu memegang aset, satu menjual, satu menyewakan. Setiap PT punya laporan sendiri, tetapi tidak ada laporan yang menunjukkan kondisi grup secara utuh. Saat bank atau investor ingin melihat gambaran besarnya, di sinilah laporan konsolidasian dibutuhkan.</p>
<h2>Apa Itu Laporan Keuangan Konsolidasian</h2>
<p>Laporan konsolidasian menyajikan induk dan seluruh entitas yang dikendalikannya seolah satu entitas ekonomi. Pengaturannya ada di PSAK 110 tentang Laporan Keuangan Konsolidasian (dulu PSAK 65). Dasarnya adalah pengendalian, bukan sekadar persentase kepemilikan: induk mengendalikan investee bila punya kuasa atas investee, terekspos pada imbal hasil variabel, dan mampu menggunakan kuasanya memengaruhi imbal hasil itu.</p>
<h2>Kapan Dibutuhkan</h2>
<ul><li><b>Bank meminta analisis grup.</b> Plafon besar, atau debitur yang agunan dan arus kasnya tersebar di beberapa PT.</li>
<li><b>Investor atau calon pembeli.</b> Mereka ingin menilai nilai gabungan dan risiko antar PT.</li>
<li><b>Persiapan IPO.</b> Calon emiten dengan entitas anak perlu laporan konsolidasian yang diaudit.</li>
<li><b>Kewajiban standar.</b> Entitas induk yang mengendalikan entitas lain pada dasarnya diwajibkan menyajikan laporan konsolidasian, dengan pengecualian tertentu seperti entitas investasi. Bila Anda tidak yakin, periksa dengan akuntan sebelum memutuskan tidak menyusunnya.</li></ul>
<h2>Langkah Menyusun</h2>
''' + T(['Langkah','Yang dikerjakan'],[
 ['1. Petakan struktur','Siapa memiliki siapa, persentase, dan siapa yang mengendalikan. Termasuk kepemilikan lewat pihak lain atau atas nama pribadi'],
 ['2. Samakan kebijakan akuntansi','Semua PT memakai standar, kebijakan penyusutan, dan periode pelaporan yang sama'],
 ['3. Identifikasi transaksi antar PT','Penjualan, pinjaman, sewa, dan biaya yang dibagi antar entitas'],
 ['4. Eliminasi','Saldo dan transaksi antar PT dihapus; investasi induk dieliminasi terhadap ekuitas anak'],
 ['5. Kepentingan non-pengendali','Bagian pemegang saham minoritas pada anak disajikan terpisah di ekuitas'],
 ['6. Pengungkapan','Struktur grup, entitas anak, dan transaksi pihak berelasi dijelaskan']]) + '''
<h2>Jebakan yang Sering Muncul</h2>
<ul><li><b>Transaksi antar PT tidak cocok.</b> PT A mencatat piutang Rp2 miliar ke PT B, sedangkan PT B mencatat utang Rp1,6 miliar. Selisih seperti ini harus ditelusuri sebelum dieliminasi.</li>
<li><b>Utang pemegang saham bercampur.</b> Pinjaman pribadi pemilik ke beberapa PT tidak ikut dieliminasi, tetapi harus disajikan jelas. Lihat juga <a href="/artikel/pisahkan-uang-pribadi-dan-perusahaan/">artikel pemisahan uang pribadi dan perusahaan</a>.</li>
<li><b>Laba antar PT belum direalisasi.</b> Penjualan aset atau persediaan antar PT yang masih berada di grup perlu penyesuaian.</li>
<li><b>Periode pelaporan berbeda.</b> Satu PT berakhir Desember, yang lain Juni, sehingga perlu penyesuaian.</li>
<li><b>Pajak.</b> Konsolidasi adalah konsep akuntansi. Setiap PT tetap melaporkan pajaknya sendiri.</li></ul>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu memetakan struktur grup, merapikan laporan tiap PT, rekonsiliasi transaksi antar PT, dan menyusun laporan konsolidasian beserta catatannya. Hasilnya dapat dipakai untuk pengajuan kredit, <a href="/artikel/laporan-keuangan-bankable-investor-ready/">investor</a>, dan audit KAP. Lihat <a href="/jasa-penyusunan-laporan-keuangan/">layanan penyusunan laporan keuangan</a>.</p>''',
faq=[['Apakah semua pemilik beberapa PT wajib membuat laporan konsolidasian?','Wajib atau tidaknya tergantung apakah ada entitas induk yang mengendalikan entitas lain dan kerangka pelaporan yang dipakai. Banyak PT milik pribadi yang sejajar tidak punya induk, sehingga tidak ada kewajiban konsolidasi, meski bank bisa tetap meminta laporan gabungan.'],
['Apa bedanya laporan konsolidasian dan laporan kombinasian?','Konsolidasian untuk induk dan anak. Kombinasian menggabungkan entitas yang berada di bawah pengendalian bersama tetapi tidak saling memiliki. Pemilihannya tergantung struktur dan tujuan.'],
['Apakah laporan konsolidasian harus diaudit?','Tidak otomatis. Bank besar, investor, atau IPO biasanya meminta yang diaudit.'],
['Berapa lama menyusunnya?','Tergantung kerapian laporan tiap PT dan banyaknya transaksi antar PT. Rekonsiliasi transaksi antar PT sering menjadi bagian paling lama.']]))

A.append(dict(
slug='menjual-bpr-persiapan-penjual-persetujuan-ojk',
seo_title='Menjual BPR: Persiapan Penjual dan Persetujuan OJK',
title='Menjual BPR: Persiapan Penjual, Penilaian, dan Persetujuan OJK untuk Pemilik Baru',
description='Pemilik BPR yang ingin menjual saham perlu menyiapkan laporan, kualitas kredit, dan calon pengendali yang lolos penilaian OJK. Ini urutan kerja dan hal yang sering menghambat.',
keyword='menjual bpr', category='Valuasi & Investor', minutes=7,
cta={'href':'/bpr-dijual/','label':'BPR Dijual dan Konsultan BPR'},
wa='Halo FA Indonesia, saya ingin menjajaki penjualan saham BPR.',
sources=[['https://www.ojk.go.id/id/regulasi/Documents/Pages/POJK-7-Tahun-2024-Bank-Perekonomian-Rakyat-dan-Bank-Perekonomian-Rakyat-Syariah/FAQ%20POJK%207%20Tahun%202024%20Bank%20Perekonomian%20Rakyat%20dan%20Bank%20Perekonomian%20Rakyat%20Syariah.pdf','OJK, FAQ POJK 7/2024 tentang BPR dan BPR Syariah'],['https://ojk.go.id:443/id/kanal/perbankan/regulasi/surat-edaran-ojk/Documents/Lampiran%20SEOJK%20FPT%20BPR.pdf','OJK, SEOJK 39/SEOJK.03/2016 tentang Penilaian Kemampuan dan Kepatutan']],
related=['valuasi-indikatif-vs-valuasi-lengkap','cara-menjual-perusahaan-atau-sebagian-saham','business-wrapping-sebelum-menjual-perusahaan','due-diligence-investor-yang-perlu-disiapkan'],
body_html='''<p>Menjual BPR berbeda dari menjual perusahaan biasa. Pembelinya harus lolos penilaian kemampuan dan kepatutan (fit and proper test) OJK bila menjadi pemegang saham pengendali, dan nilai BPR sangat dipengaruhi kualitas kredit, bukan hanya laba. Penjual yang menyiapkan semuanya lebih dulu biasanya lebih cepat sampai ke penutupan transaksi.</p>
<h2>Kenapa Pasar BPR Sedang Bergerak</h2>
<p>OJK mendorong konsolidasi industri BPR dan BPR Syariah melalui aturan seperti POJK 7/2024, termasuk penguatan permodalan. BPR yang belum memenuhi permodalan atau ingin keluar dari industri punya tiga jalan: merger, akuisisi, atau masuknya investor baru. Itu sebabnya minat pembeli, baik BPR lain maupun investor perorangan dan badan, cukup nyata.</p>
<h2>Yang Dilihat Pembeli</h2>
''' + T(['Area','Pertanyaan pembeli'],[
 ['Kualitas kredit','Rasio NPL, kolektibilitas, agunan, konsentrasi debitur, dan kecukupan cadangan kerugian'],
 ['Permodalan','Modal inti, KPMM, dan apakah perlu tambahan modal setelah akuisisi'],
 ['Kepatuhan','Temuan pemeriksaan OJK dan tindak lanjutnya, laporan bulanan, batas maksimum pemberian kredit'],
 ['Tata kelola','Direksi dan komisaris, audit internal, kepatuhan, dan manajemen risiko'],
 ['Sistem','Core banking, keamanan data, dan ketergantungan pada vendor'],
 ['Legal','Akta, izin usaha, kepemilikan saham, dan sengketa yang berjalan']]) + '''
<h2>Urutan Kerja Penjual</h2>
<ol><li><b>Rapikan laporan dan kualitas aset.</b> Bersihkan klasifikasi kredit dan dokumentasi agunan. Pembeli selalu menguji sampel kredit.</li>
<li><b>Tentukan nilai awal.</b> Valuasi BPR biasanya mempertimbangkan nilai buku yang disesuaikan, kualitas aset, dan potensi laba. Bedanya valuasi cepat dan lengkap ada di <a href="/artikel/valuasi-indikatif-vs-valuasi-lengkap/">artikel ini</a>.</li>
<li><b>Siapkan data room.</b> Laporan keuangan, hasil pemeriksaan, sampel kredit, dan dokumen korporasi.</li>
<li><b>Seleksi calon pembeli.</b> Pastikan calon pengendali berpotensi lolos penilaian kemampuan dan kepatutan OJK. Dokumen dan persyaratannya mengacu pada ketentuan OJK, termasuk SEOJK 39/SEOJK.03/2016 tentang penilaian calon pemegang saham pengendali.</li>
<li><b>Negosiasi dan perjanjian.</b> Harga, mekanisme penyesuaian bila kualitas aset berubah, dan kondisi yang harus terpenuhi sebelum penutupan.</li>
<li><b>Proses persetujuan OJK.</b> Pengalihan saham pengendali memerlukan proses di OJK. Lama prosesnya tidak bisa dipastikan, jadi jadwal perjanjian perlu memberi ruang.</li></ol>
<h2>Hal yang Sering Menghambat</h2>
<ul><li>Kualitas kredit yang ternyata lebih rendah dari yang dikira setelah pembeli mengambil sampel.</li>
<li>Calon pembeli yang tidak siap menjalani penilaian OJK, baik karena dokumen maupun rekam jejak.</li>
<li>Perbedaan harapan harga antara nilai buku dan nilai yang dibayar pembeli.</li>
<li>Pemegang saham minoritas yang belum sepakat.</li></ul>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia pernah menjalankan mandat divestasi BPR dan memahami laporan BPR dari sisi audit maupun transaksi. Kami membantu sisi penjual: valuasi awal, perapian laporan, data room, dan komunikasi dengan calon pembeli. Informasi lengkap ada di <a href="/bpr-dijual/">halaman konsultan BPR</a>. Proses persetujuan akhir tetap menjadi kewenangan OJK, dan tidak ada hasil yang bisa dijanjikan.</p>''',
faq=[['Apakah pembeli BPR harus lolos penilaian OJK?','Calon pemegang saham pengendali harus menjalani penilaian kemampuan dan kepatutan oleh OJK. Persyaratan dokumennya diatur OJK dan bisa berubah, jadi periksa ketentuan terbaru.'],
['Berapa lama proses jual beli saham BPR?','Tergantung kesiapan penjual, kecepatan due diligence, dan proses di OJK. Rencanakan dengan jadwal yang longgar.'],
['Bagaimana BPR dinilai?','Umumnya nilai buku yang disesuaikan dengan kualitas aset, ditambah pertimbangan potensi laba dan lisensi. Pendekatannya menyesuaikan kondisi masing-masing BPR.'],
['Apakah BPR yang bermasalah masih bisa dijual?','Bisa, tetapi harga dan syaratnya mengikuti kondisi permodalan dan kualitas aset, dan sering melibatkan penambahan modal oleh pembeli.']]))

A.append(dict(
slug='dokumen-transfer-pricing-master-file-local-file',
seo_title='Dokumen Transfer Pricing: Master File dan Local File',
title='Dokumen Transfer Pricing: Siapa Wajib Menyusun Master File dan Local File',
description='Perusahaan yang bertransaksi dengan pihak afiliasi bisa wajib menyusun master file dan local file. Ini batas kewajiban PMK 172/2023, isi dokumen, dan tenggat penyediaannya.',
keyword='dokumen transfer pricing', category='Pajak', minutes=7,
cta={'href':'/kalkulator-tp-doc/','label':'Kalkulator Kewajiban TP Doc'},
wa='Halo FA Indonesia, saya ingin tahu apakah perusahaan saya wajib menyusun dokumen transfer pricing.',
sources=[['https://pasal.id/peraturan/pmk/pmk-no-172-tahun-2023','PMK 172 Tahun 2023 tentang Penerapan Prinsip Kewajaran dan Kelaziman Usaha'],['https://news.ddtc.co.id/berita/nasional/1810531/sudah-mei-master-file-dan-local-file-harus-sudah-tersedia','DDTCNews, Master File dan Local File harus tersedia 4 bulan setelah akhir tahun pajak'],['https://www.ortax.org/threshold-test-apakah-perusahaan-anda-wajib-menyiapkan-tp-doc','OrtaxMedia, Threshold test kewajiban TP Doc']],
related=['laporan-keuangan-bank-dan-pajak-harus-sejalan','coretax-untuk-badan-usaha-yang-perlu-disiapkan','penyusutan-fiskal-vs-komersial-cara-hitung-pajak-tangguhan','utang-pemegang-saham-dijadikan-modal-atau-tetap-pinjaman'],
body_html='''<p>Banyak grup usaha menengah baru sadar soal transfer pricing saat pemeriksaan pajak datang. Padahal bila PT Anda bertransaksi dengan pihak afiliasi, misalnya pinjaman dari pemegang saham, jual beli dengan PT satu grup, atau jasa manajemen dari induk, ada kemungkinan Anda wajib menyiapkan dokumen penentuan harga transfer. Aturannya kini ada di PMK 172 Tahun 2023.</p>
<h2>Tiga Dokumen yang Diatur</h2>
''' + T(['Dokumen','Isi','Siapa'],[
 ['Dokumen induk (master file)','Gambaran grup: struktur, bisnis, aset tidak berwujud, pendanaan, posisi keuangan grup','Wajib pajak yang memenuhi kriteria'],
 ['Dokumen lokal (local file)','Transaksi afiliasi wajib pajak Indonesia, analisis kesebandingan, metode yang dipakai','Wajib pajak yang memenuhi kriteria'],
 ['Laporan per negara (CbCR)','Pelaporan kegiatan grup per negara','Entitas induk grup dengan peredaran bruto konsolidasi besar (batasnya Rp11 triliun)']]) + '''
<h2>Siapa yang Wajib Menyusun Master File dan Local File</h2>
<p>Syarat dasarnya adalah wajib pajak melakukan transaksi afiliasi pada tahun berjalan. Kewajiban menyusun master file dan local file muncul bila memenuhi salah satu batasan, di antaranya peredaran bruto tahun pajak sebelumnya melebihi Rp50 miliar, atau nilai transaksi afiliasi tahun sebelumnya melewati batas dalam PMK, yaitu di atas Rp20 miliar untuk transaksi barang berwujud, atau di atas Rp5 miliar untuk masing-masing jenis transaksi jasa, bunga, pemanfaatan harta tidak berwujud, dan transaksi lainnya. Perhitungan batas ini disetahunkan bila tahun pajak kurang dari 12 bulan. Karena batas dan kriterianya bisa berubah, cek ketentuan terbaru atau gunakan <a href="/kalkulator-tp-doc/">kalkulator kewajiban TP Doc</a> kami sebagai pemeriksaan awal.</p>
<p>Perusahaan yang tidak memenuhi batas tidak wajib menyusun master file dan local file, tetapi tetap harus menerapkan prinsip kewajaran dan kelaziman usaha pada transaksi afiliasinya.</p>
<h2>Tenggat yang Perlu Diingat</h2>
<ul><li>Master file dan local file harus sudah tersedia paling lama 4 bulan setelah akhir tahun pajak. Untuk tahun pajak yang berakhir Desember, artinya paling lambat akhir April.</li>
<li>Ikhtisar master file dan local file dilampirkan pada SPT Tahunan.</li>
<li>Dokumen lengkap harus diserahkan dalam 1 bulan sejak diminta dalam pengawasan kepatuhan atau pemeriksaan.</li>
<li>Dokumen disusun berdasarkan data dan informasi yang tersedia pada saat transaksi afiliasi dilakukan (pendekatan ex ante), bukan disusun belakangan dari angka yang sudah jadi.</li></ul>
<h2>Transaksi yang Paling Sering Disorot</h2>
<ul><li>Pinjaman dari pemegang saham atau afiliasi, termasuk tingkat bunganya.</li>
<li>Jasa manajemen, royalti, dan biaya bersama yang dibebankan induk.</li>
<li>Jual beli barang atau aset antar PT satu grup.</li>
<li>Penjualan dengan margin yang jauh berbeda dibanding pihak independen.</li></ul>
<p>Untuk pinjaman, ada juga batas rasio utang terhadap modal yang memengaruhi biaya bunga yang dapat dikurangkan. Lihat <a href="/artikel/utang-pemegang-saham-dijadikan-modal-atau-tetap-pinjaman/">artikel utang pemegang saham</a>.</p>
<h2>Langkah Praktis</h2>
<ol><li>Daftar semua transaksi dengan pihak afiliasi satu tahun penuh.</li>
<li>Uji batas kewajiban (peredaran bruto dan nilai transaksi).</li>
<li>Kumpulkan kontrak dan dasar penetapan harga.</li>
<li>Lakukan analisis kesebandingan dan pilih metode yang sesuai.</li>
<li>Susun dokumen dan simpan bersama bukti pendukung sebelum tenggat.</li></ol>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu memeriksa kewajiban, menyusun local file dan master file, serta menyiapkan ikhtisar untuk SPT. Penyesuaian akhir terkait pajak sebaiknya dikonsultasikan dengan konsultan pajak berizin Anda. Mulailah dari <a href="/kalkulator-tp-doc/">kalkulator kewajiban TP Doc</a>.</p>''',
faq=[['Apakah PT kecil yang punya pinjaman dari pemegang saham wajib membuat TP Doc?','Belum tentu. Kewajiban master file dan local file bergantung pada batas peredaran bruto dan nilai transaksi afiliasi. Tetapi prinsip kewajaran tetap berlaku, termasuk untuk bunga pinjaman afiliasi.'],
['Kapan dokumen harus selesai?','Master file dan local file harus tersedia paling lama 4 bulan setelah akhir tahun pajak, dan ikhtisarnya dilampirkan pada SPT Tahunan.'],
['Apa risikonya bila tidak menyusun?','Otoritas pajak dapat menilai harga transaksi dan melakukan koreksi, yang bisa berujung pajak tambahan dan sanksi. Detail risikonya perlu dikonfirmasi dengan konsultan pajak.'],
['Apakah dokumen lama bisa disusun belakangan?','Dokumen harus mencerminkan informasi yang ada saat transaksi dilakukan. Menyusun belakangan sangat berisiko dan sebaiknya dibicarakan dengan konsultan pajak.']]))
